package com.whatsaas.automation.engine;
import com.fasterxml.jackson.databind.JsonNode; import com.whatsaas.automation.domain.WorkflowExecution; import org.springframework.stereotype.Component;
@Component public class ConditionNodeProcessor implements WorkflowNodeProcessor{public String type(){return "condition";} public NodeResult process(WorkflowExecution e,JsonNode n,JsonNode c){JsonNode d=n.path("data");String actual=c.at(pointer(d.path("field").asText("/message/body"))).asText("");String expected=d.path("value").asText("");String op=d.path("operator").asText("contains");boolean ok=switch(op){case "equals"->actual.equals(expected);case "startsWith"->actual.startsWith(expected);default->actual.toLowerCase().contains(expected.toLowerCase());};return NodeResult.branch(ok?"true":"false","{\"matched\":"+ok+"}");}private String pointer(String v){return v.startsWith("/")?v:"/"+v.replace(".","/");}}
